const readline = require('readline')

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
})

const questions = [
    "What's your name?",
    "Where do you live?",
    "What are you going to do with Node.js?"
]

const addSpaceBeforeQuestion = (question) => `${question} `

function collectionAnswers(questions, done) {
    const answers = []
    const questionAnswered = answer => {
        answers.push(answer.trim())
        if (answers.length < questions.length) {
            rl.question(addSpaceBeforeQuestion(questions[answers.length]), questionAnswered)

        }
        else return done(answers)
    }
    rl.question(addSpaceBeforeQuestion(questions[0]), questionAnswered)
}

collectionAnswers(questions, (answers) => {
    console.log('Thanks for answering!')
    console.log(answers)
    process.exit()
})

